  meta=json.loads(next(f));last=-math.inf;n=0;selected=[]
  for line in f:
   row=json.loads(line);ensure(row['i']==n,'TABLE_INDEX');x=float.fromhex(row['loga']);ensure(x>last,'TABLE_ORDER');last=x
   ensure(len(row['background'])==len(row['d2background_dloga2'])==meta['bg_size'],'TABLE_WIDTH')
   ensure(all(math.isfinite(float.fromhex(v)) for v in row['background']+row['d2background_dloga2']),'TABLE_FINITE')
